macro_rules! forget_introspect {
    () => {
        emit_message!("📊 INTROSPECT: Function forget in module {}", module_path!());
    };
}

mkfn!{
    forget_introspect!();
    # [doc = " Takes ownership and \"forgets\" about the value **without running its destructor**."] # [doc = ""] # [doc = " Any resources the value manages, such as heap memory or a file handle, will linger"] # [doc = " forever in an unreachable state. However, it does not guarantee that pointers"] # [doc = " to this memory will remain valid."] # [doc = ""] # [doc = " * If you want to leak memory, see [`Box::leak`]."] # [doc = " * If you want to obtain a raw pointer to the memory, see [`Box::into_raw`]."] # [doc = " * If you want to dispose of a value properly, running its destructor, see"] # [doc = "   [`mem::drop`]."] # [doc = ""] # [doc = " # Safety"] # [doc = ""] # [doc = " `forget` is not marked as `unsafe`, because Rust's safety guarantees"] # [doc = " do not include a guarantee that destructors will always run. For example,"] # [doc = " a program can create a reference cycle using [`Rc`][rc], or call"] # [doc = " [`process::exit`][exit] to exit without running destructors. Thus, allowing"] # [doc = " `mem::forget` from safe code does not fundamentally change Rust's safety"] # [doc = " guarantees."] # [doc = ""] # [doc = " That said, leaking resources such as memory or I/O objects is usually undesirable."] # [doc = " The need comes up in some specialized use cases for FFI or unsafe code, but even"] # [doc = " then, [`ManuallyDrop`] is typically preferred."] # [doc = ""] # [doc = " Because forgetting a value is allowed, any `unsafe` code you write must"] # [doc = " allow for this possibility. You cannot return a value and expect that the"] # [doc = " caller will necessarily run the value's destructor."] # [doc = ""] # [doc = " [rc]: ../../std/rc/struct.Rc.html"] # [doc = " [exit]: ../../std/process/fn.exit.html"] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " The canonical safe use of `mem::forget` is to circumvent a value's destructor"] # [doc = " implemented by the `Drop` trait. For example, this will leak a `File`, i.e. reclaim"] # [doc = " the space taken by the variable but never close the underlying system resource:"] # [doc = ""] # [doc = " ```no_run"] # [doc = " use std::mem;"] # [doc = " use std::fs::File;"] # [doc = ""] # [doc = " let file = File::open(\"foo.txt\").unwrap();"] # [doc = " mem::forget(file);"] # [doc = " ```"] # [doc = ""] # [doc = " This is useful when the ownership of the underlying resource was previously"] # [doc = " transferred to code outside of Rust, for example by transmitting the raw"] # [doc = " file descriptor to C code."] # [doc = ""] # [doc = " # Relationship with `ManuallyDrop`"] # [doc = ""] # [doc = " While `mem::forget` can also be used to transfer *memory* ownership, doing so is error-prone."] # [doc = " [`ManuallyDrop`] should be used instead. Consider, for example, this code:"] # [doc = ""] # [doc = " ```"] # [doc = " use std::mem;"] # [doc = ""] # [doc = " let mut v = vec![65, 122];"] # [doc = " // Build a `String` using the contents of `v`"] # [doc = " let s = unsafe { String::from_raw_parts(v.as_mut_ptr(), v.len(), v.capacity()) };"] # [doc = " // leak `v` because its memory is now managed by `s`"] # [doc = " mem::forget(v);  // ERROR - v is invalid and must not be passed to a function"] # [doc = " assert_eq!(s, \"Az\");"] # [doc = " // `s` is implicitly dropped and its memory deallocated."] # [doc = " ```"] # [doc = ""] # [doc = " There are two issues with the above example:"] # [doc = ""] # [doc = " * If more code were added between the construction of `String` and the invocation of"] # [doc = "   `mem::forget()`, a panic within it would cause a double free because the same memory"] # [doc = "   is handled by both `v` and `s`."] # [doc = " * After calling `v.as_mut_ptr()` and transmitting the ownership of the data to `s`,"] # [doc = "   the `v` value is invalid. Even when a value is just moved to `mem::forget` (which won't"] # [doc = "   inspect it), some types have strict requirements on their values that"] # [doc = "   make them invalid when dangling or no longer owned. Using invalid values in any"] # [doc = "   way, including passing them to or returning them from functions, constitutes"] # [doc = "   undefined behavior and may break the assumptions made by the compiler."] # [doc = ""] # [doc = " Switching to `ManuallyDrop` avoids both issues:"] # [doc = ""] # [doc = " ```"] # [doc = " use std::mem::ManuallyDrop;"] # [doc = ""] # [doc = " let v = vec![65, 122];"] # [doc = " // Before we disassemble `v` into its raw parts, make sure it"] # [doc = " // does not get dropped!"] # [doc = " let mut v = ManuallyDrop::new(v);"] # [doc = " // Now disassemble `v`. These operations cannot panic, so there cannot be a leak."] # [doc = " let (ptr, len, cap) = (v.as_mut_ptr(), v.len(), v.capacity());"] # [doc = " // Finally, build a `String`."] # [doc = " let s = unsafe { String::from_raw_parts(ptr, len, cap) };"] # [doc = " assert_eq!(s, \"Az\");"] # [doc = " // `s` is implicitly dropped and its memory deallocated."] # [doc = " ```"] # [doc = ""] # [doc = " `ManuallyDrop` robustly prevents double-free because we disable `v`'s destructor"] # [doc = " before doing anything else. `mem::forget()` doesn't allow this because it consumes its"] # [doc = " argument, forcing us to call it only after extracting anything we need from `v`. Even"] # [doc = " if a panic were introduced between construction of `ManuallyDrop` and building the"] # [doc = " string (which cannot happen in the code as shown), it would result in a leak and not a"] # [doc = " double free. In other words, `ManuallyDrop` errs on the side of leaking instead of"] # [doc = " erring on the side of (double-)dropping."] # [doc = ""] # [doc = " Also, `ManuallyDrop` prevents us from having to \"touch\" `v` after transferring the"] # [doc = " ownership to `s` — the final step of interacting with `v` to dispose of it without"] # [doc = " running its destructor is entirely avoided."] # [doc = ""] # [doc = " [`Box`]: ../../std/boxed/struct.Box.html"] # [doc = " [`Box::leak`]: ../../std/boxed/struct.Box.html#method.leak"] # [doc = " [`Box::into_raw`]: ../../std/boxed/struct.Box.html#method.into_raw"] # [doc = " [`mem::drop`]: drop"] # [doc = " [ub]: ../../reference/behavior-considered-undefined.html"] # [inline] # [rustc_const_stable (feature = "const_forget" , since = "1.46.0")] # [stable (feature = "rust1" , since = "1.0.0")] # [rustc_diagnostic_item = "mem_forget"] pub const fn forget < T > (t : T) { let _ = ManuallyDrop :: new (t) ; }
}

