mkfn!{
    forget_unsized_introspect!();
    # [doc = " Like [`forget`], but also accepts unsized values."] # [doc = ""] # [doc = " While Rust does not permit unsized locals since its removal in [#111942] it is"] # [doc = " still possible to call functions with unsized values from a function argument"] # [doc = " or place expression."] # [doc = ""] # [doc = " ```rust"] # [doc = " #![feature(unsized_fn_params, forget_unsized)]"] # [doc = " #![allow(internal_features)]"] # [doc = ""] # [doc = " use std::mem::forget_unsized;"] # [doc = ""] # [doc = " pub fn in_place() {"] # [doc = "     forget_unsized(*Box::<str>::from(\"str\"));"] # [doc = " }"] # [doc = ""] # [doc = " pub fn param(x: str) {"] # [doc = "     forget_unsized(x);"] # [doc = " }"] # [doc = " ```"] # [doc = ""] # [doc = " This works because the compiler will alter these functions to pass the parameter"] # [doc = " by reference instead. This trick is necessary to support `Box<dyn FnOnce()>: FnOnce()`."] # [doc = " See [#68304] and [#71170] for more information."] # [doc = ""] # [doc = " [#111942]: https://github.com/rust-lang/rust/issues/111942"] # [doc = " [#68304]: https://github.com/rust-lang/rust/issues/68304"] # [doc = " [#71170]: https://github.com/rust-lang/rust/pull/71170"] # [inline] # [unstable (feature = "forget_unsized" , issue = "none")] pub fn forget_unsized < T : ? Sized > (t : T) { intrinsics :: forget (t) }
}

macro_rules! size_of_introspect {
    () => {
        emit_message!("📊 INTROSPECT: Function size_of in module {}", module_path!());
    };
}

mkfn!{
    size_of_introspect!();
    # [doc = " Returns the size of a type in bytes."] # [doc = ""] # [doc = " More specifically, this is the offset in bytes between successive elements"] # [doc = " in an array with that item type including alignment padding. Thus, for any"] # [doc = " type `T` and length `n`, `[T; n]` has a size of `n * size_of::<T>()`."] # [doc = ""] # [doc = " In general, the size of a type is not stable across compilations, but"] # [doc = " specific types such as primitives are."] # [doc = ""] # [doc = " The following table gives the size for primitives."] # [doc = ""] # [doc = " Type | `size_of::<Type>()`"] # [doc = " ---- | ---------------"] # [doc = " () | 0"] # [doc = " bool | 1"] # [doc = " u8 | 1"] # [doc = " u16 | 2"] # [doc = " u32 | 4"] # [doc = " u64 | 8"] # [doc = " u128 | 16"] # [doc = " i8 | 1"] # [doc = " i16 | 2"] # [doc = " i32 | 4"] # [doc = " i64 | 8"] # [doc = " i128 | 16"] # [doc = " f32 | 4"] # [doc = " f64 | 8"] # [doc = " char | 4"] # [doc = ""] # [doc = " Furthermore, `usize` and `isize` have the same size."] # [doc = ""] # [doc = " The types [`*const T`], `&T`, [`Box<T>`], [`Option<&T>`], and `Option<Box<T>>` all have"] # [doc = " the same size. If `T` is `Sized`, all of those types have the same size as `usize`."] # [doc = ""] # [doc = " The mutability of a pointer does not change its size. As such, `&T` and `&mut T`"] # [doc = " have the same size. Likewise for `*const T` and `*mut T`."] # [doc = ""] # [doc = " # Size of `#[repr(C)]` items"] # [doc = ""] # [doc = " The `C` representation for items has a defined layout. With this layout,"] # [doc = " the size of items is also stable as long as all fields have a stable size."] # [doc = ""] # [doc = " ## Size of Structs"] # [doc = ""] # [doc = " For `struct`s, the size is determined by the following algorithm."] # [doc = ""] # [doc = " For each field in the struct ordered by declaration order:"] # [doc = ""] # [doc = " 1. Add the size of the field."] # [doc = " 2. Round up the current size to the nearest multiple of the next field's [alignment]."] # [doc = ""] # [doc = " Finally, round the size of the struct to the nearest multiple of its [alignment]."] # [doc = " The alignment of the struct is usually the largest alignment of all its"] # [doc = " fields; this can be changed with the use of `repr(align(N))`."] # [doc = ""] # [doc = " Unlike `C`, zero sized structs are not rounded up to one byte in size."] # [doc = ""] # [doc = " ## Size of Enums"] # [doc = ""] # [doc = " Enums that carry no data other than the discriminant have the same size as C enums"] # [doc = " on the platform they are compiled for."] # [doc = ""] # [doc = " ## Size of Unions"] # [doc = ""] # [doc = " The size of a union is the size of its largest field."] # [doc = ""] # [doc = " Unlike `C`, zero sized unions are not rounded up to one byte in size."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " // Some primitives"] # [doc = " assert_eq!(4, size_of::<i32>());"] # [doc = " assert_eq!(8, size_of::<f64>());"] # [doc = " assert_eq!(0, size_of::<()>());"] # [doc = ""] # [doc = " // Some arrays"] # [doc = " assert_eq!(8, size_of::<[i32; 2]>());"] # [doc = " assert_eq!(12, size_of::<[i32; 3]>());"] # [doc = " assert_eq!(0, size_of::<[i32; 0]>());"] # [doc = ""] # [doc = ""] # [doc = " // Pointer size equality"] # [doc = " assert_eq!(size_of::<&i32>(), size_of::<*const i32>());"] # [doc = " assert_eq!(size_of::<&i32>(), size_of::<Box<i32>>());"] # [doc = " assert_eq!(size_of::<&i32>(), size_of::<Option<&i32>>());"] # [doc = " assert_eq!(size_of::<Box<i32>>(), size_of::<Option<Box<i32>>>());"] # [doc = " ```"] # [doc = ""] # [doc = " Using `#[repr(C)]`."] # [doc = ""] # [doc = " ```"] # [doc = " #[repr(C)]"] # [doc = " struct FieldStruct {"] # [doc = "     first: u8,"] # [doc = "     second: u16,"] # [doc = "     third: u8"] # [doc = " }"] # [doc = ""] # [doc = " // The size of the first field is 1, so add 1 to the size. Size is 1."] # [doc = " // The alignment of the second field is 2, so add 1 to the size for padding. Size is 2."] # [doc = " // The size of the second field is 2, so add 2 to the size. Size is 4."] # [doc = " // The alignment of the third field is 1, so add 0 to the size for padding. Size is 4."] # [doc = " // The size of the third field is 1, so add 1 to the size. Size is 5."] # [doc = " // Finally, the alignment of the struct is 2 (because the largest alignment amongst its"] # [doc = " // fields is 2), so add 1 to the size for padding. Size is 6."] # [doc = " assert_eq!(6, size_of::<FieldStruct>());"] # [doc = ""] # [doc = " #[repr(C)]"] # [doc = " struct TupleStruct(u8, u16, u8);"] # [doc = ""] # [doc = " // Tuple structs follow the same rules."] # [doc = " assert_eq!(6, size_of::<TupleStruct>());"] # [doc = ""] # [doc = " // Note that reordering the fields can lower the size. We can remove both padding bytes"] # [doc = " // by putting `third` before `second`."] # [doc = " #[repr(C)]"] # [doc = " struct FieldStructOptimized {"] # [doc = "     first: u8,"] # [doc = "     third: u8,"] # [doc = "     second: u16"] # [doc = " }"] # [doc = ""] # [doc = " assert_eq!(4, size_of::<FieldStructOptimized>());"] # [doc = ""] # [doc = " // Union size is the size of the largest field."] # [doc = " #[repr(C)]"] # [doc = " union ExampleUnion {"] # [doc = "     smaller: u8,"] # [doc = "     larger: u16"] # [doc = " }"] # [doc = ""] # [doc = " assert_eq!(2, size_of::<ExampleUnion>());"] # [doc = " ```"] # [doc = ""] # [doc = " [alignment]: align_of"] # [doc = " [`*const T`]: primitive@pointer"] # [doc = " [`Box<T>`]: ../../std/boxed/struct.Box.html"] # [doc = " [`Option<&T>`]: crate::option::Option"] # [doc = ""] # [inline (always)] # [must_use] # [stable (feature = "rust1" , since = "1.0.0")] # [rustc_promotable] # [rustc_const_stable (feature = "const_mem_size_of" , since = "1.24.0")] # [rustc_diagnostic_item = "mem_size_of"] pub const fn size_of < T > () -> usize { intrinsics :: size_of :: < T > () }
}

