mkitem!{# [doc = " Expands to the offset in bytes of a field from the beginning of the given type."] # [doc = ""] # [doc = " The type may be a `struct`, `enum`, `union`, or tuple."] # [doc = ""] # [doc = " The field may be a nested field (`field1.field2`), but not an array index."] # [doc = " The field must be visible to the call site."] # [doc = ""] # [doc = " The offset is returned as a [`usize`]."] # [doc = ""] # [doc = " # Offsets of, and in, dynamically sized types"] # [doc = ""] # [doc = " The field’s type must be [`Sized`], but it may be located in a [dynamically sized] container."] # [doc = " If the field type is dynamically sized, then you cannot use `offset_of!` (since the field's"] # [doc = " alignment, and therefore its offset, may also be dynamic) and must take the offset from an"] # [doc = " actual pointer to the container instead."] # [doc = ""] # [doc = " ```"] # [doc = " # use core::mem;"] # [doc = " # use core::fmt::Debug;"] # [doc = " #[repr(C)]"] # [doc = " pub struct Struct<T: ?Sized> {"] # [doc = "     a: u8,"] # [doc = "     b: T,"] # [doc = " }"] # [doc = ""] # [doc = " #[derive(Debug)]"] # [doc = " #[repr(C, align(4))]"] # [doc = " struct Align4(u32);"] # [doc = ""] # [doc = " assert_eq!(mem::offset_of!(Struct<dyn Debug>, a), 0); // OK — Sized field"] # [doc = " assert_eq!(mem::offset_of!(Struct<Align4>, b), 4); // OK — not DST"] # [doc = ""] # [doc = " // assert_eq!(mem::offset_of!(Struct<dyn Debug>, b), 1);"] # [doc = " // ^^^ error[E0277]: ... cannot be known at compilation time"] # [doc = ""] # [doc = " // To obtain the offset of a !Sized field, examine a concrete value"] # [doc = " // instead of using offset_of!."] # [doc = " let value: Struct<Align4> = Struct { a: 1, b: Align4(2) };"] # [doc = " let ref_unsized: &Struct<dyn Debug> = &value;"] # [doc = " let offset_of_b = unsafe {"] # [doc = "     (&raw const ref_unsized.b).byte_offset_from_unsigned(ref_unsized)"] # [doc = " };"] # [doc = " assert_eq!(offset_of_b, 4);"] # [doc = " ```"] # [doc = ""] # [doc = " If you need to obtain the offset of a field of a `!Sized` type, then, since the offset may"] # [doc = " depend on the particular value being stored (in particular, `dyn Trait` values have a"] # [doc = " dynamically-determined alignment), you must retrieve the offset from a specific reference"] # [doc = " or pointer, and so you cannot use `offset_of!` to work without one."] # [doc = ""] # [doc = " # Layout is subject to change"] # [doc = ""] # [doc = " Note that type layout is, in general, [subject to change and"] # [doc = " platform-specific](https://doc.rust-lang.org/reference/type-layout.html). If"] # [doc = " layout stability is required, consider using an [explicit `repr` attribute]."] # [doc = ""] # [doc = " Rust guarantees that the offset of a given field within a given type will not"] # [doc = " change over the lifetime of the program. However, two different compilations of"] # [doc = " the same program may result in different layouts. Also, even within a single"] # [doc = " program execution, no guarantees are made about types which are *similar* but"] # [doc = " not *identical*, e.g.:"] # [doc = ""] # [doc = " ```"] # [doc = " struct Wrapper<T, U>(T, U);"] # [doc = ""] # [doc = " type A = Wrapper<u8, u8>;"] # [doc = " type B = Wrapper<u8, i8>;"] # [doc = ""] # [doc = " // Not necessarily identical even though `u8` and `i8` have the same layout!"] # [doc = " // assert_eq!(mem::offset_of!(A, 1), mem::offset_of!(B, 1));"] # [doc = ""] # [doc = " #[repr(transparent)]"] # [doc = " struct U8(u8);"] # [doc = ""] # [doc = " type C = Wrapper<u8, U8>;"] # [doc = ""] # [doc = " // Not necessarily identical even though `u8` and `U8` have the same layout!"] # [doc = " // assert_eq!(mem::offset_of!(A, 1), mem::offset_of!(C, 1));"] # [doc = ""] # [doc = " struct Empty<T>(core::marker::PhantomData<T>);"] # [doc = ""] # [doc = " // Not necessarily identical even though `PhantomData` always has the same layout!"] # [doc = " // assert_eq!(mem::offset_of!(Empty<u8>, 0), mem::offset_of!(Empty<i8>, 0));"] # [doc = " ```"] # [doc = ""] # [doc = " [explicit `repr` attribute]: https://doc.rust-lang.org/reference/type-layout.html#representations"] # [doc = ""] # [doc = " # Unstable features"] # [doc = ""] # [doc = " The following unstable features expand the functionality of `offset_of!`:"] # [doc = ""] # [doc = " * [`offset_of_enum`] — allows `enum` variants to be traversed as if they were fields."] # [doc = " * [`offset_of_slice`] — allows getting the offset of a field of type `[T]`."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " use std::mem;"] # [doc = " #[repr(C)]"] # [doc = " struct FieldStruct {"] # [doc = "     first: u8,"] # [doc = "     second: u16,"] # [doc = "     third: u8"] # [doc = " }"] # [doc = ""] # [doc = " assert_eq!(mem::offset_of!(FieldStruct, first), 0);"] # [doc = " assert_eq!(mem::offset_of!(FieldStruct, second), 2);"] # [doc = " assert_eq!(mem::offset_of!(FieldStruct, third), 4);"] # [doc = ""] # [doc = " #[repr(C)]"] # [doc = " struct NestedA {"] # [doc = "     b: NestedB"] # [doc = " }"] # [doc = ""] # [doc = " #[repr(C)]"] # [doc = " struct NestedB(u8);"] # [doc = ""] # [doc = " assert_eq!(mem::offset_of!(NestedA, b.0), 0);"] # [doc = " ```"] # [doc = ""] # [doc = " [dynamically sized]: https://doc.rust-lang.org/reference/dynamically-sized-types.html"] # [doc = " [`offset_of_enum`]: https://doc.rust-lang.org/nightly/unstable-book/language-features/offset-of-enum.html"] # [doc = " [`offset_of_slice`]: https://doc.rust-lang.org/nightly/unstable-book/language-features/offset-of-slice.html"] # [stable (feature = "offset_of" , since = "1.77.0")] # [allow_internal_unstable (builtin_syntax)] pub macro offset_of ($ Container : ty , $ ($ fields : expr) + $ (,) ?) { { builtin # offset_of ($ Container , $ ($ fields) +) } }}